PVD("nepal_sector_nep-ai-policy-2025-nepali",{"docs":["","NEP AI Policy 2025 Nepali"],"s":{"1":[[1,"4","5","AI risk responsibility and accountability framework","ए.आई.को प्रयोगबाट सिक्जि जोक्ििको क्जम्पिेिारी िथा उत्तरदाष्ट्रयत्ि सनधािरण गनुि,",""]],"2":[[1,"4","20","AI research and development promotion (also read at p.7 §10; p.13 §16; p.16 §6)","ए.आई.को क्षेििा अनुिन्धान र ष्ट्रिकािलाई ष्ट्रििेष जोि ददने।",""]],"3":[[1,"4","29","Data privacy and security legislation (also read at p.8 §4)","गोपसनयिा, िुरक्षा प्रत्याभूसिलगायिका िाटा िुरक्षािम्पबन्धी कानुन सनिािण गने।",""]],"4":[[1,"6","9","AI excellence centers establishment (also read at p.16 §4)","5.4 पाुँचिषिसभि िबै प्रदेििा ए.आई. एक्सिलेन्ि िेन्टर स्थापना गने।",""]],"5":[[1,"6","10","AI literacy for all people","आधारभुि ििका ष्ट्रिद्याथीदेक्ि िबै व्यक्िलाई ए.आई. िाक्षर बनाउने।",""]],"6":[[1,"7","4","AI law, standards, and sectoral policy alignment (also read at p.8 §7; p.8 §9; p.13 §6; p.16 §20)","ए.आई.को प्रभािकारी व्यिस्थापनको लासग कानुन एिि् िापदण्ि िजुिा गने।",""]],"7":[[1,"7","5","AI governance and regulatory architecture (also read at p.8 §17; p.12 §24; p.14 §2; p.14 §4; p.14 §15; p.15 §25)","ए.आई. को िञ्चालन, सनयिन र प्रिििन गनि ष्ट्रिक्ििकृि िंरचना सनिािण गने।",""]],"8":[[1,"7","6","Advanced AI and digital infrastructure development (also read at p.9 §7)","ए.आई. िुँग िम्पबक्न्धि उच्च क्षििाका अत्याधुसनक पूिािधार सनिािण गने।",""]],"9":[[1,"8","12","National AI index system development (also read at p.15 §17)","ए.आई. िूचकाङ्क (National AI Index) ष्ट्रिकाि गने।",""]],"10":[[1,"8","22","AI regulatory sandbox arrangement","(Regulatory Sandbox) को व्यिस्था गने।",""]],"11":[[1,"10","10","AI startup promotion, incubation, and commercialization (also read at p.10 §11)","स्टाटिअप र निप्रिििन उद्यिलाई प्रोत्िािन र ििजीकरण गनि ए.आई.",""]],"12":[[1,"10","15","Brain gain programme for AI talent","गनि ब्रेन-गेन (Brain Gain) कायि ि िञ्चालन गने।",""]],"13":[[1,"11","5","Smart technology adoption promotion","स्िाटि क्स्िक्चङ स्िाटि सिटर लगायिका प्रष्ट्रिसधको उपयोग बढाउने।",""]],"14":[[1,"11","9","AI-enabled tourism promotion","नेपालको पयिटन प्रिििन गने।",""]],"15":[[1,"11","23","Domestic and foreign investment attraction partnerships for AI","िाझेदारी िाििि स्िदेिी िथा ष्ट्रिदेिी लगानी आकष्ट्रषि गने।",""]],"16":[[1,"12","18","AI application expansion in agriculture","प्रसिकायिलगायिका क्षेििा ए.आई.को प्रयोग बढाउने।",""]],"17":[[1,"13","1","AI-centric open data portal","ए.आई. केक्न्रि िुला िाटा पोटिल",""]],"18":[[1,"15","5","National AI center establishment","राष्ट्रिय ए.आई. केन्र स्थापना गररनेछ।",""]],"19":[[1,"16","7","AI skills development for students, researchers, and local institutions (also read at p.16 §14)","ष्ट्रिद्याथी र अनुिन्धानकिािका लासग ए.आई. िम्पबन्धी िीप ष्ट्रिकाि गनि",""]]}});
